BEGIN;

DELETE FROM questions WHERE topic = 'The Nervous System' AND subtopic IN ('All-or-Nothing & Intensity Coding', 'Impulse Propagation & Conduction Velocity', 'Neurotransmitter Release', 'Postsynaptic Receptors & Neurotransmitter Removal', 'Saltatory Conduction');

-- Q1 [Impulse Propagation & Conduction Velocity | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub1$Impulse Propagation & Conduction Velocity$sub1$, $qt1$A researcher records from one membrane segment of an unmyelinated axon while an action potential travels past it, then asks how the impulse triggers firing of the immediately downstream segment. What event opens the voltage-gated channels of that next segment?$qt1$, $op1$[{"label": "A", "text": "Na+ that entered at the active segment flows along the inside of the membrane and depolarizes the adjacent segment to threshold"}, {"label": "B", "text": "The Na+/K+ ATPase pump physically pushes the wave of depolarization down the axon as it transports Na+ outward"}, {"label": "C", "text": "K+ leaving the active segment depolarizes the adjacent membrane to threshold and opens the next segment's channels"}, {"label": "D", "text": "Neurotransmitter released along the axon membrane diffuses to the next segment and binds receptors that depolarize it"}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is A because the action potential is a self-regenerating wave driven by Na+ entry, not by a pump, by K+, or by neurotransmitter. When voltage-gated Na+ channels open at the active segment, Na+ rushes in and moves along the inside of the membrane, and its positive charge depolarizes the adjacent segment to threshold; that depolarization then opens the next segment's voltage-gated Na+ channels and the cycle repeats point by point down the axon (A&P: "the action potential is propagated because more voltage-gated Na+ channels are opened as the depolarization spreads... Na+ enters through the channel and moves along the inside of the cell membrane... new voltage-gated Na+ channels open and more ions rush into the cell, spreading the depolarization a little farther"). (Choice A) is correct because inward Na+ flow spreading to the adjacent segment is exactly the regeneration step that reopens channels down the axon. (Choice B) is wrong because the Na+/K+ pump only restores resting ion gradients after the impulse ("the Na+/K+ pump ensure that the ions return to their original locations") and does not propagate the signal. (Choice C) is wrong because K+ efflux repolarizes the membrane; it is Na+ influx, not K+ leaving, that depolarizes the next segment to threshold. (Choice D) is wrong because neurotransmitter release and receptor binding occur only at the chemical synapse between cells, whereas propagation along a single axon is purely electrical via Na+ flow. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established mechanism by which inward Na+ current regenerates the action potential at each successive membrane segment.$ex1$, 'easy', '3A', $cc1$Impulse Propagation & Synapses$cc1$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a1B$Treating the Na+/K+ pump as the active driver of propagation rather than the restorer of resting gradients$a1B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a1C$Swapping K+ efflux for Na+ influx as the depolarizing current that brings the next segment to threshold$a1C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a1D$Importing chemical synaptic transmission (neurotransmitter diffusion to receptors) into electrical propagation along a single axon$a1D$ FROM q;

-- Q2 [Impulse Propagation & Conduction Velocity | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub2$Impulse Propagation & Conduction Velocity$sub2$, $qt2$Two unmyelinated axons run side by side and differ only in caliber: one is a wide, large-diameter axon and the other a narrow, small-diameter axon. A physiologist initiates an identical action potential in each and predicts which one carries the Na+-based depolarization to the axon terminal sooner.$qt2$, $op2$[{"label": "A", "text": "The thinner axon arrives sooner, because its narrower bore concentrates the charge and drives the impulse along more quickly."}, {"label": "B", "text": "The thicker axon arrives sooner, because its larger cross-section offers lower internal resistance to the spreading Na+ depolarization."}, {"label": "C", "text": "Both axons arrive at the same instant, because conduction velocity is set by membrane threshold voltage and is independent of axon geometry."}, {"label": "D", "text": "The thicker axon arrives sooner, because its larger diameter forces the impulse to leap across longer stretches of membrane between channels."}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is B because a wider axon presents a larger cross-sectional area, which lowers the internal resistance opposing the spread of the Na+-based depolarization, so the action potential travels down it faster than down a narrow axon. The text states that "Much as water runs faster in a wide river than in a narrow creek, Na+-based depolarization spreads faster down a wide axon than down a narrow one. This concept is known as resistance" (A&P 22066-22067), and OpenStax Biology 2e confirms that "The speed of conduction of an action potential along an axon is influenced by both the diameter of the axon and the axon's resistance to current leak" (Bio 2e 46035-46036). Because the two axons are unmyelinated and identical except for caliber, diameter is the only variable that distinguishes their conduction speeds, and the larger one wins. (Choice A) is incorrect because the relationship is reversed: a narrow axon has higher internal resistance and therefore conducts more slowly, not faster, than a wide one. (Choice B) is correct because the larger cross-section of the wide axon lowers internal resistance and lets the depolarization spread faster, exactly as the wide-river analogy describes. (Choice C) is incorrect because the text explicitly names axon diameter as a determinant of conduction speed, so velocity is not independent of geometry. (Choice D) is incorrect because "leaping" between gaps describes saltatory conduction at the nodes of Ranvier, a separate myelin-based mechanism, not the diameter/resistance effect operating in these unmyelinated axons. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the textbook principle that a larger axon diameter lowers internal resistance and thereby increases conduction velocity.$ex2$, 'easy', '3A', $cc2$Impulse Propagation & Synapses$cc2$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a2A$Inverts the diameter-velocity relationship, claiming a narrow axon conducts faster when in fact its higher internal resistance makes it slower$a2A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a2C$Asserts conduction velocity is fixed by membrane threshold and independent of axon geometry, contradicting the text's explicit listing of diameter as a determinant$a2C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a2D$Attributes the wide axon's speed advantage to saltatory leaping between nodes of Ranvier, conflating the diameter/resistance mechanism with the separate myelin-based mechanism$a2D$ FROM q;

-- Q3 [Impulse Propagation & Conduction Velocity | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub3$Impulse Propagation & Conduction Velocity$sub3$, $qt3$Two axons in a peripheral nerve have identical diameters, but one is wrapped in myelin and the other is bare. A physiologist stimulates each axon at one end and records that the action potential reaches the far end of the myelinated axon much sooner. The physiologist concludes the speed difference arises because, in the myelinated axon, the action potential is:$qt3$, $op3$[{"label": "A", "text": "regenerated rapidly along the internodes, where the myelin sheath packs an unusually high density of voltage-gated Na+ channels"}, {"label": "B", "text": "slowed at each membrane patch, so the bare axon's continuous refreshing of the signal at every segment outpaces it"}, {"label": "C", "text": "regenerated only at the widely spaced nodes of Ranvier, so it effectively jumps from node to node instead of reopening Na+ channels at every adjacent segment"}, {"label": "D", "text": "triggered with less depolarization at each segment, because the myelin sheath lowers the membrane's threshold of excitation"}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is C because, in a myelinated axon, voltage-gated Na+ channels are concentrated only at the nodes of Ranvier, so the action potential is regenerated solely at those widely spaced gaps and effectively leaps from one node to the next (saltatory conduction). In an unmyelinated axon, by contrast, voltage-gated Na+ channels must reopen continuously at every adjacent patch of membrane, which is slower. The A&P text states that "Continuous conduction is slow because there are always voltage-gated Na+ channels opening... Saltatory conduction is faster because the action potential basically jumps from one node to the next," and Biology 2e adds that without nodes "Na+ and K+ channels would have to continuously regenerate action potentials at every point along the axon instead of at specific points." Because both axons share the same diameter here, the only variable distinguishing them is the node-to-node regeneration that myelin permits. (Choice A) is wrong because the internodal membrane under the myelin has essentially no voltage-gated channels—they are concentrated at the nodes, not the internodes—so this reverses where the channels actually sit. (Choice B) is wrong because continuous regeneration at every patch is precisely what makes the unmyelinated axon slower, not faster, so it reverses the true relationship. (Choice C) is correct because regeneration confined to the spaced nodes lets the impulse jump rather than crawl segment-by-segment, which is the mechanism that makes the intact myelinated axon faster. (Choice D) is wrong because myelin acts as an electrical insulator that prevents current leak and enables node-to-node jumping; it does not alter the membrane's threshold voltage. This is a Scientific Reasoning and Problem Solving question because it requires holding diameter constant, comparing two conduction mechanisms, and inferring from the scenario which structural feature accounts for the measured speed difference.$ex3$, 'medium', '3A', $cc3$Impulse Propagation & Synapses$cc3$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a3A$Plausible real structure (voltage-gated Na+ channels) relocated to the wrong site—claims high channel density along the insulated internodes rather than at the nodes$a3A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a3B$Inverts cause and effect—frames continuous per-patch regeneration (the slow mechanism) as what makes the bare axon faster$a3B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a3D$Confuses myelin's insulating/anti-leak role with an effect on threshold voltage, attributing speed to a lowered firing threshold$a3D$ FROM q;

-- Q4 [Impulse Propagation & Conduction Velocity | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub4$Impulse Propagation & Conduction Velocity$sub4$, $qt4$A neurophysiologist records conduction velocity in four unmyelinated axons from the same animal: axon W is wide and long, axon X is wide and short, axon Y is narrow and long, and axon Z is narrow and short. Knowing that the diameter effect on resistance outweighs the length effect, which axon does she predict will conduct the action potential fastest?$qt4$, $op4$[{"label": "A", "text": "Axon W, the widest one, even though it is also the longest of the four"}, {"label": "B", "text": "Axon Y, the narrowest one, because the tight path forces ions through faster"}, {"label": "C", "text": "Axon Z, the shortest one, because length is the primary determinant of speed"}, {"label": "D", "text": "Axon X, the wide-and-short one, because both of its features favor fast conduction"}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is D because axon X combines the two geometric features that both lower resistance and speed conduction: a wide diameter and a short length. The textbook frames diameter as a resistance factor, noting that "Na+-based depolarization spreads faster down a wide axon than down a narrow one," and Bio 2e confirms that conduction speed "is influenced by both the diameter of the axon and the axon's resistance to current leak." A wide diameter lowers internal resistance, and a shorter path adds less resistance, so the wide-and-short axon (X) is faster than the wide-and-long axon (W), which fights extra length-resistance. Because diameter dominates, both wide axons beat both narrow axons, and among the wide pair the shorter one wins outright. (Choice A) Axon W is wide, so it beats the narrow axons, but it is also the longest, adding length-resistance that the equally wide but shorter axon X avoids, so W is not the single fastest. (Choice B) Axon Y is the narrowest, which raises internal resistance and slows the wave—the opposite of the wide-river effect—so it is among the slowest, not the fastest. (Choice C) Axon Z is shortest, which helps, but it is narrow; since diameter outweighs length, its narrowness makes it slower than the wide axon X. (Choice D) Axon X is both wide (low resistance, the dominant factor) and short (least added resistance), so it is the fastest of the four. This is a Scientific Reasoning and Problem Solving question because it requires combining two competing geometric variables—diameter and length—and applying the rule that the diameter (resistance) effect dominates to predict which axon conducts fastest.$ex4$, 'medium', '3A', $cc4$Impulse Propagation & Synapses$cc4$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a4A$Picks the widest axon (correctly favoring diameter) but ignores that its extra length makes the equally wide shorter axon faster$a4A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a4B$Claims the narrowest axon is fastest, inverting the resistance/diameter relationship (wide-river analogy reversed)$a4B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a4C$Treats length as the primary determinant of conduction speed, overriding the dominant diameter effect$a4C$ FROM q;

-- Q5 [Impulse Propagation & Conduction Velocity | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub5$Impulse Propagation & Conduction Velocity$sub5$, $qt5$A neurophysiologist compares two axons of equal length: a thin axon wrapped in myelin and a much wider axon with no myelin at all. She measures the time for an action potential to travel the full length of each fiber and finds the wide bare axon delivers its impulse to the terminal at least as quickly as the thin myelinated one. Which prediction is consistent with this result?$qt5$, $op5$[{"label": "A", "text": "A wide unmyelinated axon can match or exceed a thin myelinated axon, because greater diameter and myelination each raise conduction velocity independently, so a large enough diameter offsets the missing myelin."}, {"label": "B", "text": "A thin myelinated axon must always conduct faster than any unmyelinated axon, because saltatory conduction is the single fastest mode and overrides every effect of axon diameter."}, {"label": "C", "text": "Two axons of a given length must conduct at identical speeds, because diameter and myelin trade off exactly so that conduction velocity is always fixed for a set length."}, {"label": "D", "text": "A wide unmyelinated axon conducts faster only because its larger diameter forces the impulse to leap between nodes of Ranvier the way a myelinated axon does."}]$op5$::jsonb, 'A', $ex5$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is A because conduction velocity depends on two separate determinants—axon diameter and resistance to current leak—and increasing either one speeds the impulse, so a large enough diameter advantage can compensate for the absence of myelin. OpenStax Biology 2e states that "The speed of conduction of an action potential along an axon is influenced by both the diameter of the axon and the axon's resistance to current leak," with myelin acting as an insulator that reduces leak (Bio 2e 46035-46037). OpenStax A&P 2e adds that "the diameter of the axon can influence the speed of conduction," because "Na+-based depolarization spreads faster down a wide axon than down a narrow one," a property called resistance (A&P 22065-22067). Because these are independent, additive factors, a wide unmyelinated fiber can have low enough internal resistance to match or beat a thin myelinated fiber whose saltatory advantage is offset by its small diameter. (Choice A) is correct because it treats diameter and myelination as separate determinants, either of which raises velocity, allowing diameter to compensate for missing myelin. (Choice B) is a tempting partial truth: myelin genuinely speeds conduction via saltatory jumping (A&P 22063), but it ignores that diameter is a distinct, additive factor (Bio 2e 46036), so a thin myelinated axon need not beat a wide bare one. (Choice C) is wrong because the two factors do not cancel to a fixed velocity; both independently raise speed and do not trade off to a constant value (A&P 22065-22067; Bio 2e 46036). (Choice D) confuses the mechanisms, because an unmyelinated axon has no nodes of Ranvier and uses continuous conduction; its speed comes from low internal resistance, not from saltatory jumping (A&P 22061-22067; Bio 2e 46039-46044). This is a Scientific Reasoning and Problem Solving question because it requires using a measured outcome to infer that two independent mechanistic determinants of velocity—diameter and myelination—combine, rather than applying a single memorized rule.$ex5$, 'hard', '3A', $cc5$Impulse Propagation & Synapses$cc5$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a5B$510-tempting trap that myelination always wins because saltatory conduction is the single fastest mode, ignoring diameter as a separate additive determinant$a5B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a5C$belief that diameter and myelin trade off to fix conduction velocity at a constant value for a given length$a5C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a5D$attributing the wide unmyelinated axon's speed to saltatory node-jumping rather than to low internal resistance under continuous conduction$a5D$ FROM q;

-- Q6 [Saltatory Conduction | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub6$Saltatory Conduction$sub6$, $qt6$A neuroscientist examines a myelinated motor axon and traces how a single action potential travels from the axon hillock toward the terminal. At each successive node of Ranvier, the membrane fully depolarizes and fires a new action potential. How does the impulse move from one node to the next along this axon?$qt6$, $op6$[{"label": "A", "text": "It is regenerated continuously and uniformly beneath the myelin, exactly as in an unmyelinated axon"}, {"label": "B", "text": "It leaps directly from one node to the next, where the voltage-gated Na+ channels are concentrated"}, {"label": "C", "text": "It is relayed by action potentials that the myelin sheath itself generates between the nodes"}, {"label": "D", "text": "It travels backward to the previous node to reinforce itself before advancing forward"}]$op6$::jsonb, 'B', $ex6$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is B because voltage-gated Na+ channels are clustered only at the nodes of Ranvier, so the action potential is regenerated only there and effectively jumps from node to node. The OpenStax A&P text states that in myelinated axons, "propagation is described as saltatory because voltage-gated channels are only found at the nodes of Ranvier and the electrical events seem to 'jump' from one node to the next." Beneath the myelin there are "no voltage-gated Na+ channels," so the depolarization spreads passively between nodes and is regenerated only when it reaches the next node's channel cluster. (Choice A) is wrong because continuous, uniform regeneration is the description of an unmyelinated axon, where the text notes there are "no voltage-gated Na+ channels until the first node of Ranvier" beneath myelin. (Choice B) is correct because saltatory conduction is defined by the impulse leaping between nodes, the only sites where Na+ channels are concentrated. (Choice C) is wrong because myelin "acts as an insulator that prevents current from leaving the axon" and is electrically inactive; it cannot generate its own action potentials. (Choice D) is wrong because the action potential "must propagate toward the axon terminals," moving forward rather than backward to the previous node. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defining mechanism of saltatory conduction and the node-restricted distribution of voltage-gated Na+ channels.$ex6$, 'easy', '3A', $cc6$Impulse Propagation & Synapses$cc6$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a6A$Treats a myelinated axon as if it regenerates the impulse continuously like an unmyelinated axon, ignoring that no Na+ channels exist under the myelin$a6A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a6C$Attributes active signal generation to the myelin sheath, which is actually a passive insulator$a6C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a6D$Reverses the unidirectional forward propagation of the action potential into backward, self-reinforcing travel$a6D$ FROM q;

-- Q7 [Saltatory Conduction | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub7$Saltatory Conduction$sub7$, $qt7$A myelinated axon conducts impulses by saltatory conduction: the internodal membrane is wrapped in insulating myelin, while the bare nodes of Ranvier are spaced along the axon. A physiologist predicts which membrane proteins must be densely enriched at each node so that the action potential can be regenerated there as it leaps down the axon. Which channels does the prediction identify?$qt7$, $op7$[{"label": "A", "text": "Acetylcholine receptors, which relay the impulse chemically across each myelin gap"}, {"label": "B", "text": "Voltage-gated Ca2+ channels, whose Ca2+ influx regenerates the action potential at the node"}, {"label": "C", "text": "Voltage-gated Na+ channels, whose Na+ influx regenerates the action potential at the node"}, {"label": "D", "text": "Na+/K+ ATPase pumps, whose active inward pumping of Na+ depolarizes the node"}]$op7$::jsonb, 'C', $ex7$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is C because the nodes of Ranvier contain voltage-gated Na+ (and K+) channels, and it is the flow of ions through the Na+ channels in particular that regenerates the action potential over and over at each node. Because the internodal membrane is insulated by myelin and lacks voltage-gated channels, the depolarization spreads passively between nodes and must be actively rebuilt at each bare node; this requires a high density of voltage-gated Na+ channels so that Na+ rushing in renews the impulse before the spreading charge falls below threshold. Saltatory conduction works precisely because these channels are clustered only at the nodes, letting the action potential 'jump' from node to node. (Choice A) Acetylcholine receptors mediate chemical transmission at synapses, not regeneration within a single axon, where the impulse propagates electrically through voltage-gated channels. (Choice B) Voltage-gated Ca2+ channels open at the axon terminal to trigger neurotransmitter release, not at the nodes to regenerate the impulse, which the text attributes specifically to Na+ channels. (Choice C) Correct: voltage-gated Na+ channels enriched at each node carry the inward Na+ current that regenerates the action potential as it leaps down the axon. (Choice D) The Na+/K+ ATPase pumps Na+ outward (and K+ inward) to maintain the resting gradient and consumes ATP; regeneration is by passive Na+ influx through voltage-gated channels, not by the pump. This is a Scientific Reasoning and Problem Solving question because it requires using the insulating property of the internode to predict which specific channel type must be concentrated at a node to rebuild the impulse, rather than recalling a definition.$ex7$, 'medium', '3A', $cc7$Impulse Propagation & Synapses$cc7$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a7A$Treating each myelin gap as a chemical synapse requiring neurotransmitter receptors instead of voltage-gated channels for electrical regeneration$a7A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a7B$Substituting voltage-gated Ca2+ channels (which act at the axon terminal for neurotransmitter release) for the Na+ channels that regenerate the impulse at nodes$a7B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a7D$Crediting nodal depolarization to active inward pumping by the Na+/K+ ATPase rather than passive Na+ influx through voltage-gated channels$a7D$ FROM q;

-- Q8 [Saltatory Conduction | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub8$Saltatory Conduction$sub8$, $qt8$A neurophysiologist records action potential conduction velocity in two axons of identical diameter: one wrapped in myelin with widely spaced nodes of Ranvier, the other completely unmyelinated. The myelinated axon conducts far faster. Which difference in voltage-gated Na+ channel behavior BEST accounts for the faster conduction in the myelinated axon?$qt8$, $op8$[{"label": "A", "text": "Myelin lowers the threshold of excitation at the nodes, so action potentials there fire after smaller depolarizations than in the unmyelinated axon"}, {"label": "B", "text": "Each node generates an action potential of larger amplitude than the action potentials produced along the unmyelinated axon"}, {"label": "C", "text": "Na+ diffuses more slowly along the insulated internode, giving the channels time to recover between successive nodes"}, {"label": "D", "text": "The impulse jumps between widely spaced nodes instead of triggering Na+ channel opening at every point along the membrane as occurs in continuous conduction"}]$op8$::jsonb, 'D', $ex8$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is D because saltatory conduction is faster than continuous conduction specifically because of where voltage-gated Na+ channels open, not how strongly or how large the response is. In an unmyelinated axon, "Continuous conduction is slow because there are always voltage-gated Na+ channels opening, and more and more Na+ is rushing into the cell" along the whole membrane, whereas in a myelinated axon "Saltatory conduction is faster because the action potential basically jumps from one node to the next" (A&P). Because voltage-gated channels are confined to the nodes of Ranvier, the depolarization spreads passively and rapidly across the insulated internodes and only regenerates at each node, so the impulse skips the slow, point-by-point channel opening required in continuous conduction. (Choice A) Myelin does not lower the threshold of excitation; the threshold is a fixed depolarization level, and speed comes from skipping internodal regeneration rather than from easier firing. (Choice B) Action potentials are all-or-none — "All action potentials peak at the same voltage (+30 mV), so one action potential is not bigger than another" — so the nodal spikes are not larger in amplitude; the difference is where they fire, not how big they are. (Choice C) This reverses the text's logic: slowness in continuous conduction is attributed to constant channel opening with "more and more Na+ rushing into the cell," not to fast diffusion being a problem, and Na+ spread along the internode actually speeds saltatory conduction. (Choice D) Correct, because confining channel opening to widely spaced nodes lets the impulse leap between them rather than regenerating at every point, which is exactly why myelinated conduction outpaces continuous conduction. This is a Scientific Reasoning and Problem Solving question because it requires contrasting the channel behavior underlying two conduction modes and predicting which mechanistic difference explains the measured velocity difference between the two axons.$ex8$, 'medium', '3A', $cc8$Impulse Propagation & Synapses$cc8$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a8A$Attributing speed gain to a lowered firing threshold rather than to skipped internodal regeneration$a8A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a8B$Confusing faster conduction with larger-amplitude (rather than all-or-none, uniform) action potentials$a8B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a8C$Inverting the text's causal claim by blaming slowness on fast diffusion instead of constant channel opening$a8C$ FROM q;

-- Q9 [Saltatory Conduction | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub9$Saltatory Conduction$sub9$, $qt9$A geneticist studies an axon carrying a mutation that abnormally shortens the internodal distance, placing the nodes of Ranvier far closer together than normal, while leaving each node fully able to reach threshold. Compared with a normally spaced myelinated axon, the geneticist predicts that an action potential traveling down the mutant axon will:$qt9$, $op9$[{"label": "A", "text": "propagate more slowly, because crowding the nodes below their optimal spacing reduces the speed even though each node still reaches threshold"}, {"label": "B", "text": "fail to propagate, because the depolarization dissipates below threshold before reaching the next node, as it would with nodes spaced too far apart"}, {"label": "C", "text": "propagate more rapidly, because adding more nodes per unit length regenerates and reinforces the action potential more frequently"}, {"label": "D", "text": "propagate at an unchanged speed, because saltatory conduction depends only on the presence of myelin and not on the spacing between nodes"}]$op9$::jsonb, 'A', $ex9$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is A because the internodal distance in a healthy myelinated axon is set to an optimal value, and squeezing the nodes closer than that optimum lowers, rather than raises, the conduction speed. The text states that "the distance between nodes is the optimal distance to keep the membrane still depolarized above threshold at the next node," and explicitly that "If the nodes were any closer together, the speed of propagation would be slower" (A&P 22055-22059). Because the mutation merely shortens the spacing without preventing each node from reaching threshold, the impulse still travels node to node but loses the speed advantage of optimal spacing — it does not fail. The slowing reflects that closely packed nodes force more frequent regeneration of the action potential, the same factor that makes continuous (unmyelinated) conduction slow (A&P 22061-22063). (Choice A) is correct: closer-than-optimal nodes still reach threshold but propagate more slowly. (Choice B) is wrong because dissipation below threshold and conduction failure is the consequence of nodes spaced too FAR apart, where "that depolarization would have fallen off too much for voltage-gated Na+ channels to be activated at the next node" (A&P 22056-22058) — not too close. (Choice C) is wrong because more frequent regeneration is precisely what makes continuous conduction slow ("there are always voltage-gated Na+ channels opening," A&P 22062), so extra nodes slow propagation rather than speeding it. (Choice D) is wrong because, although myelin does enable saltatory conduction, the text establishes that internodal distance is an "optimal" value that directly affects speed (A&P 22054-22059), so spacing is not irrelevant. This is a Scientific Reasoning and Problem Solving question because it requires predicting the functional outcome of an experimental perturbation (a spacing mutation) by reasoning from the optimal-spacing passage rather than recalling a stated fact.$ex9$, 'hard', '3A', $cc9$Impulse Propagation & Synapses$cc9$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a9B$Attributing the too-far-apart failure mode (dissipation below threshold) to nodes that are too close together$a9B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a9C$Believing more frequent action-potential regeneration speeds conduction, when frequent regeneration is what makes continuous conduction slow$a9C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a9D$Correctly noting myelin enables saltatory conduction but wrongly concluding internodal spacing is irrelevant to speed$a9D$ FROM q;

-- Q10 [Saltatory Conduction | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub10$Saltatory Conduction$sub10$, $qt10$A neurologist studies a patient whose myelin has been stripped from a long axon segment, forcing the impulse to travel by continuous conduction along the now-bare membrane instead of jumping between nodes of Ranvier. Compared with the same axon when it was myelinated and conducting saltatorily, the neurologist predicts that propagating one impulse along the demyelinated stretch will demand more of which cellular resource?$qt10$, $op10$[{"label": "A", "text": "Less ATP, because losing the myelin sheath removes a structure the neuron had to metabolically maintain"}, {"label": "B", "text": "More ATP, because the Na+/K+ pump must now restore gradients along the entire membrane rather than only at the nodes"}, {"label": "C", "text": "An unchanged amount of ATP, because each action potential is all-or-none and so costs a fixed amount of energy"}, {"label": "D", "text": "More Ca2+ extrusion, because conduction along the bare membrane drives extra Ca2+ influx the cell must pump out"}]$op10$::jsonb, 'B', $ex10$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is B because saltatory conduction's energy savings come from confining voltage-gated channels to the nodes of Ranvier, so abolishing that arrangement forces the impulse to be regenerated everywhere and admits Na+ along the whole membrane, all of which the Na+/K+ pump must then extrude. The text states that "Nodes of Ranvier also save energy for the neuron since the channels only need to be present at the nodes and not along the entire axon" (Biology 2e, 46045-46046), and continuous conduction is described as a state in which "there are always voltage-gated Na+ channels opening, and more and more Na+ is rushing into the cell" (A&P 2e, 22062-22063). Because the cell must pump out every Na+ that entered (and pump K+ back in) to restore the gradients, regenerating the impulse at every point rather than only at scattered nodes raises the total ion-pumping (ATP) burden over the whole demyelinated length. (Choice A) is wrong and reverses the relationship: the energy saving comes from restricting channel activity to the nodes (46045), so forcing continuous regeneration increases ATP cost rather than lowering it. (Choice B) is correct because continuous conduction admits Na+ across the entire membrane, and restoring those gradients along the whole length requires more pumping than restoring them only at nodes (46044-46046). (Choice C) is a partial truth: each action potential is indeed all-or-none in amplitude, but regenerating it at every point along the membrane lets far more total Na+ enter to be pumped back out, so the integrated energy cost is not fixed (46044-46046). (Choice D) is an adjacent fact that misattributes the ion: nodal and continuous regeneration of the impulse run through voltage-gated Na+ and K+ channels (46040-46041), not axonal Ca2+ entry. This is a Scientific Reasoning and Problem Solving question because it requires chaining the channel-distribution principle to a metabolic prediction about an experimentally altered (demyelinated) axon rather than recalling a single stated fact.$ex10$, 'hard', '3A', $cc10$Impulse Propagation & Synapses$cc10$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a10A$Inverts the cause of the energy saving — claims removing myelin lowers ATP cost when confining channels to nodes is what saves energy$a10A$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a10C$Correct that an action potential is all-or-none, but wrongly concludes total energy is fixed regardless of how many points regenerate it$a10C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a10D$Swaps the relevant ion — invokes Ca2+ pumping when axonal regeneration uses Na+ and K+ channels$a10D$ FROM q;

-- Q11 [All-or-Nothing & Intensity Coding | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub11$All-or-Nothing & Intensity Coding$sub11$, $qt11$A sensory neuron firing in response to a faint touch is then exposed to a much stronger, clearly suprathreshold touch. A physiologist records the membrane voltage of each action potential the neuron fires under the stronger stimulus. Compared with the action potentials evoked by the faint touch, what does the physiologist observe about the individual spikes evoked by the stronger touch?$qt11$, $op11$[{"label": "A", "text": "Each action potential reaches a higher peak voltage, producing a taller spike, because the stronger stimulus drives more Na+ into the cell."}, {"label": "B", "text": "Each action potential lasts longer, producing a wider spike, because the stronger stimulus holds the voltage-gated Na+ channels open longer."}, {"label": "C", "text": "Each action potential reaches the same peak voltage, producing a spike of identical height, because every action potential the neuron fires peaks at about +30 mV."}, {"label": "D", "text": "Each action potential has a threshold pushed below -55 mV, producing an earlier spike, because the stronger stimulus resets the activation gate."}]$op11$::jsonb, 'C', $ex11$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is C because the action potential is an all-or-none event: once threshold is crossed, every action potential a given neuron fires runs the identical course and peaks at the same voltage, so a stronger stimulus cannot make a single spike any taller. The text states that "All action potentials peak at the same voltage (+30 mV), so one action potential is not bigger than another," and that "Stronger stimuli will initiate multiple action potentials more quickly, but the individual signals are not bigger." Stimulus intensity is therefore encoded by the frequency (and number) of action potentials, not by their amplitude. (Choice A) is wrong because a taller spike from extra Na+ influx is exactly the intensity-equals-amplitude error the all-or-none principle refutes; the peak is fixed at about +30 mV regardless of how far past threshold the stimulus drives the membrane. (Choice B) is wrong because action potential duration is set by the intrinsic kinetics of the voltage-gated channels (the inactivation gate "closes after a specific period of time—on the order of a fraction of a millisecond"), not by how strong the stimulus is. (Choice C) is correct because every action potential the neuron fires reaches the same peak voltage, so the stronger stimulus yields spikes of identical height. (Choice D) is wrong because threshold is a fixed membrane value ("Once the membrane reaches that voltage [-55 mV]... This is what is known as the threshold"); stimulus strength does not lower or reset that value. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the all-or-none principle—that action potential amplitude is fixed and independent of suprathreshold stimulus strength.$ex11$, 'easy', '3A', $cc11$Impulse Propagation & Synapses$cc11$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a11A$Stronger stimulus produces a larger-amplitude action potential (intensity equals amplitude)$a11A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a11B$Action potential duration is determined by stimulus strength rather than by intrinsic channel kinetics$a11B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a11D$Stimulus strength shifts the fixed -55 mV threshold value$a11D$ FROM q;

-- Q12 [All-or-Nothing & Intensity Coding | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub12$All-or-Nothing & Intensity Coding$sub12$, $qt12$A sensory neuron in the skin responds to a light touch with a steady train of action potentials. When the pressure on the same patch of skin is increased substantially, the neuron continues to fire identical-amplitude action potentials. How does this single neuron encode the greater stimulus intensity to the central nervous system?$qt12$, $op12$[{"label": "A", "text": "It fires a single action potential of larger amplitude that the brain interprets as a stronger signal"}, {"label": "B", "text": "It conducts each action potential faster down the axon, and the increased velocity signals the greater intensity"}, {"label": "C", "text": "It raises its resting membrane potential closer to threshold so that each spike carries more charge"}, {"label": "D", "text": "It fires the same-sized action potentials at a higher frequency, encoding the greater intensity as the rate of firing"}]$op12$::jsonb, 'D', $ex12$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is D because action potentials obey the all-or-none principle, so a more intense stimulus cannot make a bigger spike — it can only make spikes occur more often. The text states that "Stronger stimuli will initiate multiple action potentials more quickly, but the individual signals are not bigger," meaning the neuron represents increased intensity by increasing firing frequency (a rate code) rather than amplitude. Because "All action potentials peak at the same voltage (+30 mV), so one action potential is not bigger than another," the only variable the neuron can modulate to report a stronger touch is the number of spikes per unit time. (Choice A) is wrong because a stronger stimulus "will not make a 'bigger' action potential" — amplitude is fixed at +30 mV, so intensity is never coded as spike size. (Choice B) is wrong because conduction velocity is determined by myelination and axon diameter ("Na+-based depolarization spreads faster down a wide axon than down a narrow one"), not by how strong the stimulus is. (Choice C) is wrong because the resting potential is the pre-spike baseline, not the encoded output, and shifting it would not change the fixed peak charge of each all-or-none spike. (Choice D) is correct because identical spikes fired at a higher frequency are exactly how a stronger stimulus is encoded. This is a Scientific Reasoning and Problem Solving question because it requires inferring, from the all-or-none property, which physical feature of the spike train can vary to carry intensity information.$ex12$, 'medium', '3A', $cc12$Impulse Propagation & Synapses$cc12$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a12A$intensity-as-amplitude (violates all-or-none: bigger stimulus = bigger spike)$a12A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a12B$conduction velocity (set by myelination/diameter) misattributed to stimulus strength$a12B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a12C$confuses resting baseline with encoded output and misstates charge-per-spike as variable$a12C$ FROM q;

-- Q13 [All-or-Nothing & Intensity Coding | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub13$All-or-Nothing & Intensity Coding$sub13$, $qt13$A physiologist records the membrane voltage from a single sensory neuron's axon while progressively increasing the intensity of a mechanical stimulus applied to its receptor. As the stimulus grows stronger, how does the recorded train of action potentials most likely change on the voltage trace?$qt13$, $op13$[{"label": "A", "text": "The spikes remain identical in height, but successive spikes occur closer together in time."}, {"label": "B", "text": "The spikes grow progressively taller while the spacing between successive spikes stays the same."}, {"label": "C", "text": "The spikes keep the same height and spacing, but each individual spike becomes wider."}, {"label": "D", "text": "The spikes become both taller and more closely spaced as the stimulus intensifies."}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is A because action potentials are all-or-none events of fixed amplitude, so a stronger stimulus is encoded by firing more action potentials per unit time rather than by producing larger ones. The text states that "All action potentials peak at the same voltage (+30 mV), so one action potential is not bigger than another" and that "Stronger stimuli will initiate multiple action potentials more quickly, but the individual signals are not bigger" (A&P lines 21984-21985). On the recorded trace, this frequency coding appears as spikes of unchanged height that crowd closer together as intensity rises. (Choice A) Correct: identical-height spikes that occur closer together in time is exactly the predicted frequency-coded response to a stronger stimulus. (Choice B) Incorrect: taller spikes would mean amplitude coding, but "A stronger stimulus... will not make a 'bigger' action potential" because spikes are all-or-none (A&P lines 21981-21982). (Choice C) Incorrect: spike width reflects the timing of voltage-gated channel gating, which closes "on the order of a fraction of a millisecond" independent of stimulus intensity (A&P lines 21996-21997), so the trace would not broaden as the stimulus grows. (Choice D) Incorrect: the increased firing frequency is right, but adding an amplitude increase is forbidden by the all-or-none rule that every spike peaks at the same +30 mV (A&P lines 21982-21984). This is a Scientific Reasoning and Problem Solving question because it requires applying the all-or-none principle to predict the specific pattern a stronger stimulus produces on an actual voltage recording.$ex13$, 'medium', '3A', $cc13$Impulse Propagation & Synapses$cc13$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a13B$amplitude-coding belief that a stronger stimulus produces a larger action potential, directly contradicting the all-or-none rule$a13B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a13C$spike width is governed by channel gating kinetics, a real property, but is wrongly invoked as the variable that encodes stimulus intensity$a13C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a13D$correctly identifies higher firing frequency but wrongly couples it with an amplitude increase that all-or-none forbids$a13D$ FROM q;

-- Q14 [All-or-Nothing & Intensity Coding | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub14$All-or-Nothing & Intensity Coding$sub14$, $qt14$A sensory neuron fires a train of action potentials in response to a painful stimulus, and a downstream neuron in the pain pathway must determine how intense that stimulus was. Because every action potential in the train reaches the identical peak voltage, a physiologist asks how the downstream neuron can still extract intensity information from the incoming train.$qt14$, $op14$[{"label": "A", "text": "It reads intensity directly from the amplitude of each incoming spike, because a more intense stimulus produces a taller action potential."}, {"label": "B", "text": "It reads intensity from how frequently the spikes arrive, because all-or-none firing makes every spike the same size."}, {"label": "C", "text": "It reads intensity from the conduction velocity of the incoming spikes, because a more intense stimulus is conducted faster along the axon."}, {"label": "D", "text": "It reads intensity partly from the spike frequency and partly from the height of the largest spikes in the train."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is B because the all-or-none property makes every action potential identical in amplitude, so the only feature of the train that can vary with stimulus strength is how often the spikes arrive. The A&P text states that "All action potentials peak at the same voltage (+30 mV), so one action potential is not bigger than another," and that "Stronger stimuli will initiate multiple action potentials more quickly, but the individual signals are not bigger" (A&P 21984-21986); Biology 2e reinforces that "once the threshold potential is reached, the neuron always completely depolarizes" (45987-45988). A downstream neuron therefore cannot recover intensity from spike size, because there is no size difference to read; intensity is encoded only as firing frequency. (Choice A) is wrong because it denies all-or-none, assuming amplitude scales with stimulus strength, but every spike peaks at the same voltage. (Choice B) is correct because rate (frequency) is the only feature of an all-or-none train that carries the intensity signal. (Choice C) is wrong because conduction velocity is set by axon diameter and myelination, not by how intense the stimulus is — "the diameter of the axon can influence the speed of conduction" and saltatory conduction along myelinated axons is faster (A&P 22061-22069). (Choice D) is wrong because, although it correctly names frequency, it smuggles in an amplitude cue that all-or-none firing rules out, since the "largest spikes" are no taller than any others. This is a Scientific Reasoning and Problem Solving question because it requires chaining the all-or-none property to its consequence for downstream decoding and rejecting a partially correct frequency-plus-amplitude trap.$ex14$, 'hard', '3A', $cc14$Impulse Propagation & Synapses$cc14$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a14A$amplitude_coding_denies_all_or_none$a14A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a14C$velocity_depends_on_intensity_not_diameter_myelination$a14C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a14D$frequency_correct_but_smuggles_amplitude_cue$a14D$ FROM q;

-- Q15 [All-or-Nothing & Intensity Coding | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub15$All-or-Nothing & Intensity Coding$sub15$, $qt15$A sensory neuron is stimulated twice in succession: first by a stimulus that depolarizes its membrane to exactly the -55 mV threshold, and then by a stimulus that drives the membrane far past threshold. An electrophysiologist records the action potentials evoked in each case and is asked to predict how the two recordings differ.$qt15$, $op15$[{"label": "A", "text": "The far-above-threshold stimulus produces action potentials that reach a higher peak voltage, but it fires them at the same frequency as the threshold stimulus."}, {"label": "B", "text": "Both stimuli produce same-peak action potentials, but the far-above-threshold stimulus makes each spike rise to its peak faster and reach the axon terminal sooner."}, {"label": "C", "text": "Both stimuli produce action potentials that peak at the same voltage, but the far-above-threshold stimulus fires them at a higher frequency."}, {"label": "D", "text": "Both stimuli produce same-peak action potentials at the same frequency, but the far-above-threshold stimulus releases more neurotransmitter per spike."}]$op15$::jsonb, 'C', $ex15$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is C because, once threshold is crossed, every action potential in a given axon is an all-or-none event that runs the identical course to the same +30 mV peak, so the only way a neuron encodes a stronger stimulus is by firing more action potentials per unit time. The text states that "a stronger stimulus, which might depolarize the membrane well past threshold, will not make a 'bigger' action potential" and that "all action potentials peak at the same voltage (+30 mV), so one action potential is not bigger than another," while "stronger stimuli will initiate multiple action potentials more quickly" (A&P 21981-21986). Thus the far-above-threshold stimulus changes firing frequency, not spike amplitude; the spike's rising speed and conduction velocity are fixed by Na+/K+ channel kinetics, axon diameter, and myelination rather than by stimulus size (A&P 22061-22067), and the transmitter released downstream is gated by the all-or-none Ca2+ influx of an identical spike (Biology 2e 46093-46095). (Choice A) is wrong because it reverses which variable changes, claiming amplitude coding when the text says all spikes peak at the same +30 mV and only frequency rises. (Choice B) is a tempting partial truth: it correctly keeps the peak constant but wrongly ties the spike's rise time and conduction speed to stimulus strength, when those are set by channel kinetics, axon diameter, and myelination, not by how hard the membrane is pushed past threshold. (Choice C) is correct because both spikes reach the same peak voltage and the only difference is the higher firing frequency driven by the stronger stimulus. (Choice D) is wrong because transmitter release per spike is gated by the all-or-none Ca2+ influx of an identical action potential, so a larger upstream stimulus does not load each individual spike with more neurotransmitter. This is a Scientific Reasoning and Problem Solving question because it requires applying the all-or-none principle to a two-stimulus scenario and rejecting amplitude-, kinetics-, and release-based traps to predict that intensity is encoded by frequency alone.$ex15$, 'hard', '3A', $cc15$Impulse Propagation & Synapses$cc15$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a15A$amplitude coding reverses which variable changes (peak voltage rises instead of frequency)$a15A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a15B$keeps peak constant but wrongly attributes faster spike rise/conduction to stimulus strength rather than channel kinetics and myelination$a15B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a15D$more neurotransmitter released per spike, ignoring that release is gated by the all-or-none Ca2+ influx of an identical action potential$a15D$ FROM q;

-- Q16 [Neurotransmitter Release | easy | Skill 1 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub16$Neurotransmitter Release$sub16$, $qt16$An action potential travels down a motor neuron and arrives at the synaptic end bulb, where it depolarizes the terminal membrane and triggers the release of neurotransmitter into the synaptic cleft. The voltage-gated ion channel that opens in the end-bulb membrane to directly set this release in motion is the:$qt16$, $op16$[{"label": "A", "text": "voltage-gated potassium (K+) channel, which opens at the terminal so that K+ exits the end bulb and drives neurotransmitter release"}, {"label": "B", "text": "ligand-gated sodium (Na+) channel, which opens in the end bulb as the action potential arrives and admits Na+ to release transmitter"}, {"label": "C", "text": "mechanically gated chloride (Cl-) channel, which opens at the terminal to admit Cl- and cause the vesicles to fuse"}, {"label": "D", "text": "voltage-gated calcium (Ca2+) channel, which opens as the terminal depolarizes and admits Ca2+ to trigger vesicle fusion"}]$op16$::jsonb, 'D', $ex16$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is D because the arriving action potential depolarizes the synaptic end-bulb membrane, opening voltage-gated Ca2+ channels that let Ca2+ flow into the terminal and trigger vesicle fusion. OpenStax Anatomy & Physiology 2e states that "When an action potential reaches the axon terminals, voltage-gated Ca2+ channels in the membrane of the synaptic end bulb open," after which "the concentration of Ca2+ increases inside the end bulb" and "the Ca2+ facilitates the merging of the vesicle with the presynaptic membrane." OpenStax Biology 2e confirms this sequence: depolarization "causes voltage-gated Ca2+ channels to open," and "Calcium ions entering the cell initiate a signaling cascade that causes... synaptic vesicles... to fuse with the presynaptic membrane." The trigger is therefore Ca2+ entry through a voltage-gated channel, not K+ exit, ligand binding, or a chloride flux. (Choice A) is wrong because voltage-gated K+ channels mediate repolarization, where "Potassium ions reach equilibrium when the membrane voltage is below -70 mV," not vesicle release. (Choice B) is wrong because ligand-gated channels sit on the postsynaptic membrane, where transmitter "binds to ligand-gated ion channels in the postsynaptic membrane," and they respond to neurotransmitter rather than to the arriving voltage change. (Choice C) is wrong because mechanically gated channels open "in response to pressure, touch, stretching, and sound," and admitting Cl- does not trigger release. (Choice D) is correct because the depolarized end bulb opens voltage-gated Ca2+ channels whose inward Ca2+ current drives exocytosis. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling which specific channel type and ion couple terminal depolarization to neurotransmitter release.$ex16$, 'easy', '3A', $cc16$Impulse Propagation & Synapses$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a16A$Real voltage-gated K+ channel cited, but assigned the release-trigger role instead of its true repolarization role$a16A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a16B$Ligand-gated channel placed presynaptically and made voltage-triggered, confusing postsynaptic receptor channels with the presynaptic release trigger$a16B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a16C$Invents a wrong gate type (mechanical) and wrong ion (Cl-) for the release trigger$a16C$ FROM q;

-- Q17 [Neurotransmitter Release | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub17$Neurotransmitter Release$sub17$, $qt17$A presynaptic axon terminal is depolarized, and a researcher watches as neurotransmitter-filled synaptic vesicles merge with the presynaptic membrane and discharge their contents into the synaptic cleft. The cellular process the researcher is observing is BEST identified as:$qt17$, $op17$[{"label": "A", "text": "endocytosis, in which the presynaptic membrane folds inward to package neurotransmitter into a vesicle and release it into the cleft"}, {"label": "B", "text": "facilitated diffusion, in which neurotransmitter moves through a carrier protein in the presynaptic membrane down its gradient into the cleft"}, {"label": "C", "text": "exocytosis, in which the synaptic vesicle fuses with the presynaptic membrane so the neurotransmitter is expelled into the cleft"}, {"label": "D", "text": "active transport, in which a membrane pump uses ATP to push individual neurotransmitter molecules across the presynaptic membrane into the cleft"}]$op17$::jsonb, 'C', $ex17$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is C because neurotransmitter is released when a synaptic vesicle fuses with the presynaptic membrane and discharges its contents into the cleft, which is the defining feature of exocytosis. OpenStax Anatomy & Physiology 2e states that "the Ca2+ facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis into the small gap between the cells, known as the synaptic cleft." OpenStax Biology 2e likewise describes "membrane-bound vesicles, called synaptic vesicles, containing neurotransmitter molecules to fuse with the presynaptic membrane," after which "fusion of a vesicle with the presynaptic membrane causes neurotransmitter to be released into the synaptic cleft." Because the cargo is packaged in a vesicle that fuses with the plasma membrane to export bulk contents, the process is exocytosis rather than any carrier- or pump-mediated movement of single molecules. (Choice A) Endocytosis is the opposite of release; OpenStax defines exocytosis as "taking 'out of the cell,'" so a process that folds the membrane inward to bring material in cannot be how transmitter is expelled. (Choice B) Facilitated diffusion is a real transport mode in which solutes cross via a carrier protein, but transmitter is released by vesicle fusion, not by carrier-mediated diffusion of free molecules. (Choice C) Exocytosis is correct because the vesicle fuses with the presynaptic membrane and expels its neurotransmitter into the synaptic cleft. (Choice D) Active transport uses an ATP-driven pump to move individual molecules against or across a membrane, whereas release here is bulk vesicle fusion, not molecule-by-molecule pumping. This is a Knowledge of Scientific Concepts and Principles question because it requires the student to identify the named cellular mechanism (exocytosis) that the textbook directly assigns to vesicle fusion and neurotransmitter discharge.$ex17$, 'easy', '3A', $cc17$Impulse Propagation & Synapses$cc17$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a17A$Naming the inverse membrane-trafficking process (endocytosis, material into the cell) as the mechanism of release$a17A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a17B$Substituting a genuine membrane transport mode (carrier-mediated facilitated diffusion) for vesicular release$a17B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a17D$Treating bulk vesicle fusion as molecule-by-molecule ATP-driven pumping$a17D$ FROM q;

-- Q18 [Neurotransmitter Release | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub18$Neurotransmitter Release$sub18$, $qt18$An action potential reaches a presynaptic axon terminal and voltage-gated Ca2+ channels open, so Ca2+ rushes into the synaptic end bulb. A neurophysiologist asks a student to predict the very next molecular event the incoming Ca2+ produces inside the terminal that leads to neurotransmitter release.$qt18$, $op18$[{"label": "A", "text": "Ca2+ associates with proteins on the outer surface of the neurotransmitter vesicles and facilitates their fusion with the presynaptic membrane, releasing transmitter by exocytosis"}, {"label": "B", "text": "Ca2+ binds receptor proteins on the postsynaptic membrane and opens their ion channels, depolarizing the target cell directly"}, {"label": "C", "text": "Ca2+ is pumped back out across the presynaptic membrane, and that outward movement squeezes the vesicles into the synaptic cleft"}, {"label": "D", "text": "Ca2+ opens voltage-gated Na+ channels in the terminal so that incoming Na+ drives the vesicles to fuse with the membrane"}]$op18$::jsonb, 'A', $ex18$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is A because, once Ca2+ enters the synaptic end bulb, it acts directly on the vesicles: it associates with proteins on the outer surface of the neurotransmitter vesicles and facilitates their merging with the presynaptic membrane, releasing transmitter by exocytosis. The Anatomy & Physiology text states that "the Ca2+ ion associates with proteins in the outer surface of neurotransmitter vesicles" and that "the Ca2+ facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis." Biology 2e likewise notes that "Calcium ions entering the cell initiate a signaling cascade that causes small membrane-bound vesicles... to fuse with the presynaptic membrane," confirming that fusion is the immediate Ca2+-driven event, not a postsynaptic or efflux event. (Choice A) is correct because Ca2+ binding to vesicle-surface proteins triggers vesicle fusion and exocytosis. (Choice B) is wrong because binding receptors and opening their channels on the postsynaptic membrane is the later step performed by the neurotransmitter after it crosses the cleft, not by Ca2+ in the terminal. (Choice C) is wrong because it is Ca2+ influx, not efflux, that triggers fusion; no outward pumping squeezes vesicles into the cleft. (Choice D) is wrong because depolarization opens the voltage-gated Ca2+ channels rather than the reverse, and Na+ entry does not trigger vesicle fusion. This is a Scientific Reasoning and Problem Solving question because it requires predicting, from the stated Ca2+ influx, the specific downstream molecular event that produces neurotransmitter release while rejecting plausible but misplaced alternatives.$ex18$, 'medium', '3A', $cc18$Impulse Propagation & Synapses$cc18$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'process_step_confusion', $a18B$Attributing the later postsynaptic receptor-binding step to Ca2+ acting in the presynaptic terminal$a18B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a18C$Inventing a Ca2+ efflux mechanism for fusion when influx is what triggers exocytosis$a18C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a18D$Reversing the depolarization–Ca2+ channel causality and substituting Na+ entry as the fusion trigger$a18D$ FROM q;

-- Q19 [Neurotransmitter Release | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub19$Neurotransmitter Release$sub19$, $qt19$A marine toxin selectively and irreversibly blocks the voltage-gated Ca2+ channels in the presynaptic axon terminals of a cholinergic neuron, yet each action potential still propagates down the axon and depolarizes the terminal membrane normally. A physiologist records from the postsynaptic cell during repeated presynaptic firing and is asked to predict what happens at this synapse.$qt19$, $op19$[{"label": "A", "text": "Neurotransmitter is still released into the cleft, because the action potential's depolarization of the terminal is by itself sufficient to drive vesicle fusion."}, {"label": "B", "text": "No neurotransmitter is released into the cleft, because Ca2+ cannot enter the terminal to trigger the fusion of synaptic vesicles with the presynaptic membrane."}, {"label": "C", "text": "Neurotransmitter floods continuously into the cleft, because the blocked Ca2+ channels lock the synaptic vesicles permanently fused to the presynaptic membrane."}, {"label": "D", "text": "Neurotransmitter is still released but cannot act, because the block also closes the ligand-gated receptor channels on the postsynaptic membrane."}]$op19$::jsonb, 'B', $ex19$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is B because Ca2+ entry through the presynaptic voltage-gated Ca2+ channels is the obligatory trigger for vesicle fusion, so blocking those channels prevents neurotransmitter release even though the action potential still arrives. The text states that "When an action potential reaches the axon terminals, voltage-gated Ca2+ channels in the membrane of the synaptic end bulb open. The concentration of Ca2+ increases inside the end bulb... The Ca2+ facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis into the synaptic cleft" (A&P 2e). Likewise, Biology 2e notes that "voltage-gated Ca2+ channels open and allow Ca2+ to enter the cell. The calcium entry causes synaptic vesicles to fuse with the membrane and release neurotransmitter." If the Ca2+ channels are blocked, the depolarization arrives but no Ca2+ enters, vesicles do not fuse, and the cleft never receives transmitter. (Choice A) is wrong because the depolarization is only an upstream step; the text makes Ca2+ influx—not depolarization alone—the event that "facilitates the merging of the vesicle with the presynaptic membrane." (Choice B) is correct because with no Ca2+ entry there is no fusion and therefore no release into the synaptic cleft. (Choice C) reverses the causal relationship: blocking Ca2+ entry prevents fusion rather than locking vesicles permanently fused and releasing transmitter continuously. (Choice D) is wrong because the toxin acts only on presynaptic Ca2+ channels; the postsynaptic ligand-gated receptors are a separate component and, in any case, no transmitter is released for them to bind. This is a Scientific Reasoning and Problem Solving question because it requires predicting the downstream consequence of a specific molecular perturbation by reasoning through the Ca2+-dependent fusion step of the release mechanism.$ex19$, 'medium', '3A', $cc19$Impulse Propagation & Synapses$cc19$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a19A$Action potential and depolarization do arrive, but learner omits that Ca2+ influx is the required trigger for vesicle fusion$a19A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a19C$Treats blocking Ca2+ entry as locking vesicles fused (continuous release) instead of preventing fusion$a19C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a19D$Invokes postsynaptic ligand-gated receptors, a real but separate component unaffected by a presynaptic Ca2+-channel block$a19D$ FROM q;

-- Q20 [Neurotransmitter Release | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub20$Neurotransmitter Release$sub20$, $qt20$A presynaptic neuron is bathed in a saline solution from which all extracellular Ca2+ has been removed. When the axon is stimulated, intracellular recordings confirm that the presynaptic action potential reaches the terminal with its normal amplitude and time course, yet no postsynaptic response is detected. The experimenter wants to localize the broken step in synaptic transmission.$qt20$, $op20$[{"label": "A", "text": "The defect is upstream: without Ca2+, the action potential can no longer reach or depolarize the axon terminal, so the terminal never becomes active."}, {"label": "B", "text": "The defect is postsynaptic: removing Ca2+ leaves release intact but prevents neurotransmitter from binding its receptors across the cleft."}, {"label": "C", "text": "The defect is in removal: without Ca2+, the released transmitter is not cleared, so it lingers and desensitizes the receptors, silencing the response."}, {"label": "D", "text": "The defect is in release: with no Ca2+ to enter the open channels, synaptic vesicles fail to fuse, so no neurotransmitter is exocytosed into the cleft."}]$op20$::jsonb, 'D', $ex20$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is D because the action potential and its Na+-driven depolarization still occur, but with no extracellular Ca2+ available to enter when the voltage-gated Ca2+ channels open, the Ca2+-triggered fusion of synaptic vesicles cannot happen, so no transmitter is exocytosed. The text states that when an action potential reaches the terminal, voltage-gated Ca2+ channels open and 'Calcium ions entering the cell initiate a signaling cascade that causes... synaptic vesicles... to fuse with the presynaptic membrane' (Biology 2e), and that 'The Ca2+ facilitates the merging of the vesicle with the presynaptic membrane so that the neurotransmitter is released through exocytosis' (A&P 2e). Because the stem fixes the presynaptic spike as normal but the postsynaptic response as absent, the only step that depends on the missing variable—extracellular Ca2+ influx—is vesicle fusion and release, pinpointing that as the break. (Choice A) is wrong because action potential conduction into the terminal depends on voltage-gated Na+ channels, not on extracellular Ca2+, and the stem explicitly reports the presynaptic spike is unchanged. (Choice B) is wrong because neurotransmitter-receptor binding is a key-and-lock event across the cleft that does not require extracellular Ca2+, and here the block is presynaptic, before any transmitter is released. (Choice C) is wrong because clearance by degradation or reuptake is a later step that acts on already-released transmitter; the response is lost because nothing is released, not because nothing is cleared. (Choice D) is correct because removing the Ca2+ that must enter to trigger fusion abolishes exocytosis while leaving the upstream electrical signal intact. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental manipulation, holding the unchanged presynaptic action potential as a control, and reasoning from the absent postsynaptic response to localize the defect to the specific Ca2+-dependent fusion step.$ex20$, 'hard', '3A', $cc20$Impulse Propagation & Synapses$cc20$, 'biology', 2, 160
  ) RETURNING id
)
