UNION ALL SELECT id, 'C', 'process_step_confusion', $a20C$Confusing the upstream release step with the downstream neurotransmitter-clearance step$a20C$ FROM q;

-- Q21 [Postsynaptic Receptors & Neurotransmitter Removal | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub21$Postsynaptic Receptors & Neurotransmitter Removal$sub21$, $qt21$At a cholinergic synapse, a motor neuron releases acetylcholine into the cleft, where it binds postsynaptic nicotinic receptors. A physiologist asks how the acetylcholine is normally cleared from the cleft so that it can no longer bind the receptor and reopen the channel. Which mechanism accomplishes this clearance?$qt21$, $op21$[{"label": "A", "text": "An enzyme, acetylcholinesterase, breaks the acetylcholine down within the cleft so it can no longer bind the receptor."}, {"label": "B", "text": "A presynaptic transporter pumps the intact acetylcholine back into the axon terminal to be repackaged and released again."}, {"label": "C", "text": "The acetylcholine simply diffuses laterally out of the cleft without any enzyme acting on it."}, {"label": "D", "text": "Neighboring glial cells take up the intact acetylcholine and recycle the unaltered molecule."}]$op21$::jsonb, 'A', $ex21$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is A because at the cholinergic synapse the neurotransmitter is eliminated by the enzyme acetylcholinesterase (AChE), which chemically degrades acetylcholine in the cleft. The text states that "the ACh in the synaptic cleft is degraded by the enzyme acetylcholinesterase (AChE) so that the ACh cannot rebind to a receptor and reopen its channel," and that for the cholinergic synapse "the neurotransmitter is eliminated by acetylcholinesterase." Enzymatic degradation is one of three named clearance routes (enzymatic degradation, neuronal reuptake, or glial reuptake), and it is the specific one used for acetylcholine. (Choice A) Correct: acetylcholinesterase enzymatically breaks down the acetylcholine in the cleft so it can no longer bind the receptor. (Choice B) Incorrect: reuptake of the intact transmitter into the presynaptic terminal is how serotonin, dopamine, and norepinephrine are removed, not acetylcholine. (Choice C) Incorrect: passive lateral diffusion alone is not the clearance route the text assigns to acetylcholine, which is actively degraded by AChE. (Choice D) Incorrect: glial uptake and recycling of the intact molecule applies to amino-acid transmitters such as glutamate, not to acetylcholine. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the specific enzymatic-degradation clearance mechanism that the textbook assigns to acetylcholine at the cholinergic synapse.$ex21$, 'easy', '3A', $cc21$Impulse Propagation & Synapses$cc21$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a21B$Applying the presynaptic reuptake route (correct for serotonin/dopamine/norepinephrine) to acetylcholine$a21B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a21C$Naming a real diffusion process but treating passive diffusion, not enzymatic degradation, as the ACh clearance route$a21C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a21D$Applying glial reuptake/recycling (correct for amino-acid transmitters like glutamate) to acetylcholine$a21D$ FROM q;

-- Q22 [Postsynaptic Receptors & Neurotransmitter Removal | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub22$Postsynaptic Receptors & Neurotransmitter Removal$sub22$, $qt22$A neurologist administers a drug that strongly inhibits acetylcholinesterase at the cholinergic synapses of the neuromuscular junction, where this enzyme is the route by which released acetylcholine (ACh) is normally cleared from the cleft. Compared with an untreated junction receiving the same presynaptic input, what should the neurologist predict for the postsynaptic muscle membrane?$qt22$, $op22$[{"label": "A", "text": "It becomes hyperpolarized and inhibited, because the extra acetylcholine that accumulates in the cleft drives the membrane further from threshold."}, {"label": "B", "text": "It undergoes prolonged, amplified depolarization, because the lingering acetylcholine repeatedly rebinds its receptors and keeps their channels reopening."}, {"label": "C", "text": "It stops responding almost at once, because acetylcholine that is never degraded can no longer bind to and activate its postsynaptic receptors."}, {"label": "D", "text": "It depolarizes normally and recovers on schedule, because presynaptic reuptake rapidly clears the acetylcholine in the enzyme's place."}]$op22$::jsonb, 'B', $ex22$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is B because acetylcholinesterase (AChE) is the clearance route for ACh at the cholinergic neuromuscular junction, and when it is inhibited the ACh that has already been released is not broken down, so it lingers in the cleft and can rebind receptors and reopen their channels. The text states that ACh binding opens a receptor channel through which positive ions enter, causing the muscle fiber to depolarize, and that AChE normally degrades the ACh "so that the ACh cannot rebind to a receptor and reopen its channel, which would cause unwanted extended muscle excitation and contraction." Removing that degradation therefore does the opposite of stopping the signal: the same excitatory (depolarizing) stimulus is prolonged and amplified because the transmitter keeps reactivating its receptors instead of being cleared. (Choice A) is wrong because ACh at the NMJ opens cation channels that depolarize and excite the membrane, so accumulating more ACh strengthens depolarization rather than hyperpolarizing or inhibiting the cell. (Choice B) is correct because undegraded ACh persists in the cleft and repeatedly rebinds its receptors, extending and intensifying the depolarizing postsynaptic response. (Choice C) is wrong because degradation by AChE terminates signaling after ACh has bound; it is not a prerequisite for binding, so undegraded ACh still binds and activates its receptors. (Choice D) is wrong because ACh is eliminated by enzymatic degradation rather than by presynaptic reuptake, so with AChE blocked there is no reuptake pathway standing by to clear it. This is a Scientific Reasoning and Problem Solving question because it requires predicting the downstream postsynaptic consequence of an experimental enzyme inhibition by reasoning from the mechanism of ACh action and clearance rather than recalling a single stated fact.$ex22$, 'medium', '3A', $cc22$Impulse Propagation & Synapses$cc22$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a22A$Treats added excitatory transmitter as if it produced inhibition/hyperpolarization, inverting the direction of ACh's effect at the NMJ$a22A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a22C$Confuses the order of synaptic steps, casting degradation as what enables receptor binding rather than what terminates signaling after binding$a22C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a22D$Imports a real clearance mechanism (presynaptic reuptake) that applies to other transmitter systems but not to ACh at the cholinergic synapse$a22D$ FROM q;

-- Q23 [Postsynaptic Receptors & Neurotransmitter Removal | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub23$Postsynaptic Receptors & Neurotransmitter Removal$sub23$, $qt23$A neuropharmacologist studies a synapse that uses serotonin (a biogenic amine) and asks how the released serotonin is normally cleared from the cleft so the terminal can be reset for the next signal. The drug being tested is known to act on the protein responsible for that clearance step. Which mechanism normally terminates serotonin's action at this synapse?$qt23$, $op23$[{"label": "A", "text": "An esterase in the synaptic cleft chemically degrades the serotonin into inactive fragments"}, {"label": "B", "text": "The postsynaptic cell engulfs the serotonin through receptor-mediated endocytosis"}, {"label": "C", "text": "A transporter in the presynaptic membrane pumps the intact serotonin back into the terminal for reuse"}, {"label": "D", "text": "The serotonin is inactivated solely by passive diffusion out of the synaptic cleft"}]$op23$::jsonb, 'C', $ex23$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is C because biogenic amines such as serotonin are removed from the synaptic cleft by reuptake: a transport protein in the presynaptic membrane carries the intact, undegraded molecule back into the terminal, where it is repackaged into vesicles and released again. OpenStax A&P 2e states that "Serotonin is transported back into the presynaptic cell for repackaging" and, more generally, that a "pump in the cell membrane of the presynaptic element... will clear the [transmitter] from the synaptic cleft so that it can be recycled, repackaged in vesicles, and released again." This contrasts with acetylcholine, the only major transmitter listed whose elimination is "Degradation by acetylcholinesterase" rather than reuptake (A&P 2e). Because the question asks which single route applies to a monoamine, the enzymatic answer is a tempting but incorrect cross-over from the cholinergic system. (Choice A) describes acetylcholine's route, where the transmitter is "eliminated by acetylcholinesterase," not serotonin's, which is recovered intact. (Choice B) names receptor-mediated endocytosis by the postsynaptic cell, which is not a transmitter-clearance pathway; clearance is performed by the presynaptic terminal or glia, not by postsynaptic engulfment. (Choice C) is correct because serotonin "is transported back into the presynaptic cell" by a presynaptic membrane transporter for repackaging and reuse. (Choice D) overstates diffusion; although the small cleft does allow rapid diffusion of transmitter, the dominant, signal-terminating route for monoamines is active reuptake, not passive escape alone. This is a Scientific Reasoning and Problem Solving question because it requires selecting the correct clearance mechanism for a specified transmitter class and distinguishing it from the enzymatic route used by acetylcholine rather than recalling a single isolated fact.$ex23$, 'medium', '3A', $cc23$Impulse Propagation & Synapses$cc23$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a23A$Applying acetylcholine's acetylcholinesterase degradation route to a monoamine transmitter$a23A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a23B$Inventing a postsynaptic endocytosis clearance pathway that does not exist$a23B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a23D$Diffusion is real in the cleft but is not the dominant termination route for monoamines$a23D$ FROM q;

-- Q24 [Postsynaptic Receptors & Neurotransmitter Removal | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub24$Postsynaptic Receptors & Neurotransmitter Removal$sub24$, $qt24$A neuron releases a single transmitter into a cleft where the postsynaptic membrane carries both an ionotropic receptor and a metabotropic receptor that recognize that same transmitter. A pharmacologist predicts how each receptor will shape the postsynaptic response after the transmitter binds.$qt24$, $op24$[{"label": "A", "text": "The metabotropic receptor gives the faster response because its G protein conducts ions through the receptor pore, while the ionotropic receptor must first generate cAMP."}, {"label": "B", "text": "Both receptors change the membrane potential with identical speed because each one opens an integral ion channel the instant the transmitter binds."}, {"label": "C", "text": "The ionotropic receptor produces the slow modulatory effect because it activates adenylate cyclase, while the metabotropic receptor opens an ion pore for the fast effect."}, {"label": "D", "text": "The ionotropic receptor gives the fast direct change in membrane potential because it is itself a ligand-gated channel, while the metabotropic receptor acts slowly through a G protein and a second messenger such as cAMP."}]$op24$::jsonb, 'D', $ex24$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is D because the ionotropic receptor is itself a ligand-gated ion channel that opens directly when the transmitter binds, whereas the metabotropic receptor is not a channel and must work through a G protein and an effector that makes a second messenger, a slower multi-step route. OpenStax A&P 2e states that "Ionotropic receptors are ligand-gated ion channels," and that an ionotropic receptor "is a channel that opens when the neurotransmitter binds to it," giving an immediate ion flux and change in membrane potential. By contrast, the metabotropic receptor complex includes "the transmembrane receptor protein, a G protein, and an effector protein," and the G protein "physically moves from the receptor protein to the effector protein to activate the latter," which then generates a second messenger such as cAMP; OpenStax Biology 2e likewise shows the ligand-gated channel opening to produce a "localized depolarization or hyperpolarization," while the G-protein route runs as "a cyclic series of events." Because the metabotropic pathway requires G-protein activation and second-messenger synthesis before any ion channel is modulated, it is inherently slower and modulatory rather than a direct, fast potential change. (Choice A) is wrong because it reverses the receptors: the G protein does not conduct ions through the receptor pore, and it is the metabotropic, not the ionotropic, receptor that uses cAMP. (Choice B) is a partial truth that fails because the metabotropic receptor is not itself a channel, so the two responses cannot have identical speed. (Choice C) swaps the mechanisms, wrongly assigning adenylate cyclase and the slow effect to the ionotropic channel and a fast ion pore to the metabotropic receptor. (Choice D) correctly pairs the ligand-gated channel with the fast direct potential change and the GPCR with the slow second-messenger effect. This is a Scientific Reasoning and Problem Solving question because it requires chaining each receptor's molecular identity to a predicted difference in response kinetics rather than recalling a single labeled fact.$ex24$, 'hard', '3A', $cc24$Impulse Propagation & Synapses$cc24$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
