UNION ALL SELECT id, 'B', 'partial_truth', $a24B$Correctly notes the ionotropic receptor opens an integral channel on binding but wrongly extends this to the metabotropic receptor, ignoring that the GPCR is not itself a channel$a24B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a24C$Swaps the adenylate-cyclase/second-messenger mechanism onto the ionotropic receptor and the direct ion-pore mechanism onto the metabotropic receptor$a24C$ FROM q;

-- Q25 [Postsynaptic Receptors & Neurotransmitter Removal | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Nervous System', $sub25$Postsynaptic Receptors & Neurotransmitter Removal$sub25$, $qt25$A patient begins taking a selective serotonin reuptake inhibitor (SSRI), a drug that blocks the presynaptic transporter that normally pumps serotonin back into the serotonergic terminal. At a serotonergic synapse where reuptake is the dominant clearance route and no cleft enzyme degrades this transmitter, a researcher predicts how the drug changes signaling at the postsynaptic receptors. Which prediction is correct?$qt25$, $op25$[{"label": "A", "text": "Serotonin accumulates in the cleft and keeps binding its receptors, prolonging and intensifying postsynaptic signaling."}, {"label": "B", "text": "Acetylcholinesterase in the cleft rapidly degrades the un-recycled serotonin, so cleft transmitter levels stay normal."}, {"label": "C", "text": "The presynaptic terminal can no longer release more serotonin, so postsynaptic signaling falls sharply."}, {"label": "D", "text": "The serotonin building up in the cleft is hyperpolarizing, so it inhibits rather than prolongs postsynaptic firing."}]$op25$::jsonb, 'A', $ex25$This is a Biology question that falls under the content category 'Impulse Propagation & Synapses'. The answer is A because blocking the reuptake transporter removes serotonin's only clearance pathway at this synapse, so the transmitter lingers in the cleft and keeps binding postsynaptic receptors. The textbook states that "Selective serotonin reuptake inhibitors (SSRIs) block the reuptake of serotonin into the presynaptic neuron. This blockage results in an increase in serotonin in the synaptic cleft" (Biology 2e), and serotonin "is transported back into the presynaptic cell for repackaging" (A&P 2e), confirming reuptake is its route of removal. The text's parallel acetylcholinesterase example shows that when removal is blocked the transmitter "stays in the cleft and can continually bind and unbind to postsynaptic receptors," which is exactly the prolonged, intensified signaling produced here. (Choice A) is correct: with no enzyme to substitute for the blocked transporter, serotonin builds up and repeatedly re-binds its receptors, extending the postsynaptic response. (Choice B) is wrong because acetylcholinesterase acts only on acetylcholine—it does not degrade serotonin, which is cleared by reuptake, not by a cleft enzyme. (Choice C) is wrong because it confuses clearance with release; vesicular release is a separate Ca2+-triggered exocytosis step that the reuptake blocker does not disable. (Choice D) is wrong because serotonin's accumulation prolongs and strengthens its existing receptor-mediated signaling rather than reversing it into hyperpolarizing inhibition. This is a Scientific Reasoning and Problem Solving question because it requires predicting the downstream synaptic consequence of a specific molecular perturbation by integrating the clearance route, the absence of a substitute enzyme, and the resulting receptor-binding effect.$ex25$, 'hard', '3A', $cc25$Impulse Propagation & Synapses$cc25$, 'biology', 2, 160
  ) RETURNING id
)
